def pad_edge_right(mat, targeth, targetw, side):
 h,w=len(mat),len(mat[0]); m=[row+[1]*(targetw-w) for row in mat]+[[1]*targetw for _ in range(targeth-h)]
 if side=='R': return [r[-1] for r in m]
 if side=='L': return [r[0] for r in m]
 if side=='T': return m[0]
 if side=='B': return m[-1]
def solve_pad(arrs):
 sols=[]; best=100
 for p in permutations(range(4)):
  for oo in product(range(4),repeat=4):
   m=[rots(arrs[p[i]])[oo[i]] for i in range(4)]
   a,b,c,d=m
   htop=max(len(a),len(b)); hbot=max(len(c),len(d)); wleft=max(len(a[0]),len(c[0])); wright=max(len(b[0]),len(d[0]))
   ar=pad_edge_right(a,htop,wleft,'R'); bl=pad_edge_right(b,htop,wright,'L')
   cr=pad_edge_right(c,hbot,wleft,'R'); dl=pad_edge_right(d,hbot,wright,'L')
   ab=pad_edge_right(a,htop,wleft,'B'); ct=pad_edge_right(c,hbot,wleft,'T')
   bb=pad_edge_right(b,htop,wright,'B'); dt=pad_edge_right(d,hbot,wright,'T')
   cost=sum(x!=y for x,y in zip(ar,bl))+sum(x!=y for x,y in zip(cr,dl))+sum(x!=y for x,y in zip(ab,ct))+sum(x!=y for x,y in zip(bb,dt))
   if cost<best: best=cost; sols=[]
   if cost==best: sols.append((p,oo,[(len(x),len(x[0])) for x in m],(htop,hbot,wleft,wright)))
 return best,sols[:10],len(sols)
