def best_row(arrs):
 out=[]
 for p in permutations(range(4)):
  for oo in product(range(4),repeat=4):
   m=[rots(arrs[p[i]])[oo[i]] for i in range(4)]; H=max(len(a) for a in m)
   cost=0; contacts=0
   for a,b in zip(m,m[1:]):
    e1=pad_edge_right(a,H,len(a[0]),'R'); e2=pad_edge_right(b,H,len(b[0]),'L')
    cost+=sum(x!=y for x,y in zip(e1,e2))
    contacts+=sum(x==y and x!=1 for x,y in zip(e1,e2))
   rot=sum(min(k,4-k) for k in oo)
   out.append((cost,rot,-contacts,p,oo,[(len(x),len(x[0])) for x in m]))
 return sorted(out)
